"use strict";

const fs = require("fs");
const path = require("path");
const { parseYaml } = require("./parse-yaml");
const {
  IMAGE_MEDIA_INCLUDE,
  RESPONSIVE_MEDIA_INCLUDE,
  SUPPORTED_FIELD_TYPES,
  withMediaChain,
} = require("./constants");
const { indentBlock, isUnlimited, relationshipTs, toPascalCase, uuidv5 } = require("./helpers");
const { normalizeParagraph, validateAll } = require("./validate");

const GENERATED_BANNER = `/**
 * @generated by \`npm run paragraphs:generate\`
 * Do not edit this file. Change definitions in /paragraphs instead.
 */
`;

function rootDir() {
  return path.resolve(__dirname, "../..");
}

function loadYamlFile(filePath) {
  return parseYaml(fs.readFileSync(filePath, "utf8"), path.relative(rootDir(), filePath));
}

function loadDefinitions(root) {
  const dir = path.join(root, "paragraphs");
  const projectFile = path.join(dir, "_project.yaml");
  if (!fs.existsSync(projectFile)) {
    throw new Error(`Missing ${projectFile}`);
  }

  const project = loadYamlFile(projectFile);
  const files = fs
    .readdirSync(dir)
    .filter((name) => name.endsWith(".yaml") && !name.startsWith("_"))
    .sort();

  const paragraphs = files.map((name) => {
    const filePath = path.join(dir, name);
    return normalizeParagraph(loadYamlFile(filePath), `paragraphs/${name}`);
  });

  return { project, projectFile: "paragraphs/_project.yaml", paragraphs };
}

function extraList(project, key) {
  const value = project[key];
  return Array.isArray(value) ? value.map(String) : [];
}

function buildRegistryModel(project, paragraphs) {
  const byId = new Map(paragraphs.map((def) => [def.id, def]));
  const nested = new Set(extraList(project, "extraNestedFields"));
  const imageFields = {};
  const multiImageFields = {};
  const nestedResponsive = [];
  const selfResponsive = [];

  for (const def of paragraphs) {
    for (const [fieldName, field] of Object.entries(def.fields)) {
      if (field.type === "paragraph") {
        nested.add(fieldName);
      }
      if (field.media === "single") {
        imageFields[`paragraph--${def.id}`] = fieldName;
      }
      if (field.media === "multi") {
        multiImageFields[`paragraph--${def.id}`] = fieldName;
      }
      if (field.media === "nested_responsive") {
        nested.add(fieldName);
        if (!nestedResponsive.includes(`paragraph--${def.id}`)) {
          nestedResponsive.push(`paragraph--${def.id}`);
        }
      }
      if (field.media === "self") {
        if (!selfResponsive.includes(`paragraph--${def.id}`)) {
          selfResponsive.push(`paragraph--${def.id}`);
        }
      }
    }
    if (def.mapping === "responsive_media" && !selfResponsive.includes(`paragraph--${def.id}`)) {
      selfResponsive.push(`paragraph--${def.id}`);
    }
  }

  const extraImages = project.extraImageFields || {};
  for (const [type, field] of Object.entries(extraImages)) {
    if (type && field) imageFields[type] = String(field);
  }

  const nodeBundles = {};
  const includeSuffixes = {};

  for (const [bundle, config] of Object.entries(project.nodeBundles || {})) {
    nodeBundles[bundle] = [...(config.paragraphFields || [])];
    for (const nodeField of config.paragraphFields || []) {
      if (!includeSuffixes[nodeField]) includeSuffixes[nodeField] = new Set();
    }
  }

  function suffixesForField(fieldName, field, depth) {
    if (field.type === "media") {
      return withMediaChain(fieldName, IMAGE_MEDIA_INCLUDE);
    }
    if (field.type === "paragraph" && field.media === "nested_responsive") {
      return withMediaChain(fieldName, RESPONSIVE_MEDIA_INCLUDE);
    }
    const paths = [fieldName];
    if (field.type === "paragraph" && field.target && field.target !== "*" && field.recurse !== false && depth < 3) {
      const target = byId.get(field.target);
      if (target) {
        for (const [childName, child] of Object.entries(target.fields)) {
          if (child.type !== "paragraph" && child.type !== "media") continue;
          for (const suffix of suffixesForField(childName, child, depth + 1)) {
            paths.push(`${fieldName}.${suffix}`);
          }
        }
      }
    }
    return paths;
  }

  for (const def of paragraphs) {
    for (const parent of def.parents) {
      const bucket = includeSuffixes[parent.through];
      if (!bucket) continue;

      if (parent.field !== parent.through) {
        bucket.add(parent.field);
      }

      for (const [fieldName, field] of Object.entries(def.fields)) {
        if (field.type !== "paragraph" && field.type !== "media") continue;
        const relSuffixes = suffixesForField(fieldName, field, 0);
        for (const suffix of relSuffixes) {
          if (parent.field === parent.through) {
            bucket.add(suffix);
          } else {
            bucket.add(`${parent.field}.${suffix}`);
          }
        }
      }
    }
  }

  const extraIncludes = project.extraIncludeSuffixes || {};
  for (const [nodeField, suffixes] of Object.entries(extraIncludes)) {
    if (!includeSuffixes[nodeField]) includeSuffixes[nodeField] = new Set();
    for (const suffix of suffixes || []) {
      includeSuffixes[nodeField].add(suffix);
    }
  }

  const includeObject = {};
  for (const [field, set] of Object.entries(includeSuffixes)) {
    includeObject[field] = [...set].sort();
  }

  return {
    nodeBundles,
    nestedFields: [...nested].sort(),
    includeSuffixes: includeObject,
    imageFields,
    multiImageFields,
    nestedResponsive: nestedResponsive.sort(),
    selfResponsive: selfResponsive.sort(),
    withImage: extraList(project, "extraTypesWithImage"),
  };
}

function tsForField(field) {
  const spec = SUPPORTED_FIELD_TYPES[field.type];
  if (spec.kind === "relationship") {
    return relationshipTs(field);
  }
  if (field.type === "link" && isUnlimited(field) && spec.tsUnlimited) {
    return spec.tsUnlimited;
  }
  return spec.ts;
}

function renderTypes(paragraphs) {
  const blocks = paragraphs.map((def) => {
    const attrsName = `${def.component || toPascalCase(def.id)}Attributes`;
    const resourceName = `${def.component || toPascalCase(def.id)}Resource`;
    const fieldLines = Object.entries(def.fields).map(([name, field]) => {
      return `  ${name}?: ${indentBlock(tsForField(field), 2)};`;
    });

    return `export type ${attrsName} = {
  parent_id?: string | null;
  parent_type?: string | null;
  parent_field_name?: string | null;
${fieldLines.join("\n")}
  [key: string]: unknown;
};

export type ${resourceName} = JsonApiResource<"paragraph--${def.id}", ${attrsName}>;`;
  });

  return `${GENERATED_BANNER}
import type { JsonApiResource } from "../types";

${blocks.join("\n\n")}
`;
}

function renderRegistry(model) {
  const nodeBundleEntries = Object.entries(model.nodeBundles)
    .map(([bundle, fields]) => `  ${bundle}: ${JSON.stringify(fields)},`)
    .join("\n");

  const includeEntries = Object.entries(model.includeSuffixes)
    .map(([field, suffixes]) => {
      const lines = suffixes.map((suffix) => `    ${JSON.stringify(suffix)},`).join("\n");
      return `  ${field}: [\n${lines}\n  ],`;
    })
    .join("\n");

  const imageEntries = Object.entries(model.imageFields)
    .map(([type, field]) => `  ${JSON.stringify(type)}: ${JSON.stringify(field)},`)
    .join("\n");
  const multiEntries = Object.entries(model.multiImageFields)
    .map(([type, field]) => `  ${JSON.stringify(type)}: ${JSON.stringify(field)},`)
    .join("\n");

  return `${GENERATED_BANNER}
import type { NodeBundle } from "../config";

export const NODE_PARAGRAPH_FIELDS_BY_BUNDLE: Record<NodeBundle, readonly string[]> = {
${nodeBundleEntries}
};

export const NESTED_PARAGRAPH_FIELDS = ${JSON.stringify(model.nestedFields)} as const;

export const INCLUDE_SUFFIXES_BY_NODE_FIELD: Record<string, readonly string[]> = {
${includeEntries}
};

export const PARAGRAPH_IMAGE_FIELDS: Record<string, string> = {
${imageEntries}
};

export const PARAGRAPH_MULTI_IMAGE_FIELDS: Record<string, string> = {
${multiEntries}
};

export const PARAGRAPH_TYPES_WITH_IMAGE = ${JSON.stringify(model.withImage)} as const;

export const PARAGRAPH_TYPES_RESPONSIVE_MEDIA = ${JSON.stringify(model.selfResponsive)} as const;

export const PARAGRAPH_TYPES_WITH_NESTED_RESPONSIVE_MEDIA = ${JSON.stringify(model.nestedResponsive)} as const;

export function allNodeParagraphFields(): string[] {
  return [...new Set(Object.values(NODE_PARAGRAPH_FIELDS_BY_BUNDLE).flat())];
}

export function includeForBundle(bundle: NodeBundle): string {
  const nodeFields = NODE_PARAGRAPH_FIELDS_BY_BUNDLE[bundle] ?? [];
  const paths = new Set<string>();

  for (const field of nodeFields) {
    paths.add(field);
    const suffixes = INCLUDE_SUFFIXES_BY_NODE_FIELD[field] ?? [];
    for (const suffix of suffixes) {
      paths.add(\`\${field}.\${suffix}\`);
    }
  }

  return [...paths].join(",");
}

export function nodeParagraphFieldsForBundle(bundle: NodeBundle): readonly string[] {
  return NODE_PARAGRAPH_FIELDS_BY_BUNDLE[bundle] ?? [];
}
`;
}

function mappingNeeds(def) {
  const values = Object.values(def.fields);
  return {
    image: values.some((field) => field.media === "single") || def.passImage,
    images: values.some((field) => field.media === "multi"),
    responsiveMedia: values.some((field) => field.media === "nested_responsive"),
    filterResponsive: values.some((field) => field.media === "nested_responsive"),
  };
}

function renderDefaultMappingEntry(def) {
  const needs = mappingNeeds(def);
  const ctxArgs = [];
  if (needs.image || needs.images || needs.responsiveMedia) ctxArgs.push("page");
  if (def.renderChildren) ctxArgs.push("renderChildren");
  const ctx = ctxArgs.length ? `{ ${ctxArgs.join(", ")} }` : "_ctx";

  const props = [
    `        key={item.resource.id}`,
    `        paragraph={item.resource as Parameters<typeof ${def.component}>[0]["paragraph"]}`,
  ];
  if (needs.image) props.push(`        image={page.paragraphImages[item.resource.id] ?? null}`);
  if (needs.images) props.push(`        images={page.paragraphImageLists[item.resource.id] ?? []}`);
  if (needs.responsiveMedia) props.push(`        responsiveMedia={page.paragraphResponsiveMedia[item.resource.id] ?? null}`);

  const prelude = needs.filterResponsive
    ? `    const contentChildren = item.children.filter((child) => child.resource.type !== "paragraph--responsive_media");\n\n`
    : "";

  if (!def.renderChildren) {
    return `  "paragraph--${def.id}": (item, ${ctx}) => {
    return (
      <${def.component}
${props.join("\n")}
      />
    );
  },`;
  }

  const childrenExpr = needs.filterResponsive ? "{renderChildren(contentChildren)}" : "{renderChildren(item.children)}";

  return `  "paragraph--${def.id}": (item, ${ctx}) => {
${prelude}    return (
      <${def.component}
${props.join("\n")}
      >
        ${childrenExpr}
      </${def.component}>
    );
  },`;
}

function renderComponentMapping(paragraphs) {
  const imports = [];
  const seen = new Set();
  const entries = [];

  for (const def of paragraphs) {
    if (!def.component || def.mapping === "none") continue;
    if (!seen.has(def.component)) {
      seen.add(def.component);
      imports.push(`import { ${def.component} } from "./${def.component}/${def.component}";`);
    }

    if (def.mapping === "responsive_media") {
      entries.push(`  "paragraph--${def.id}": (item, { page }) => {
    const media = page.paragraphResponsiveMedia[item.resource.id];
    if (!media) return null;

    return (
      <${def.component}
        key={item.resource.id}
        media={media}
      />
    );
  },`);
      continue;
    }

    entries.push(renderDefaultMappingEntry(def));
  }

  return `${GENERATED_BANNER}
import type { DrupalPage, ParagraphItem } from "@/lib/drupal";
import type { ReactNode } from "react";
${imports.join("\n")}

export type ParagraphRenderContext = {
  page: DrupalPage;
  renderChildren: (children: ParagraphItem[]) => ReactNode;
};

export const generatedParagraphComponents: Record<string, (item: ParagraphItem, ctx: ParagraphRenderContext) => ReactNode> = {
${entries.join("\n\n")}
};
`;
}

function componentStub(def) {
  const attrsName = `${def.component}Attributes`;
  return `import type { ${attrsName}, JsonApiResource } from "@/lib/drupal";
import clsx from "clsx";
import styles from "./${def.component}.module.scss";

type ${def.component}Props = {
  paragraph: JsonApiResource<"paragraph--${def.id}", ${attrsName}>;
  children?: React.ReactNode;
};

export function ${def.component}({ paragraph, children }: ${def.component}Props) {
  const { attributes } = paragraph;

  return (
    <div className={clsx(styles.root)}>
      <pre>{JSON.stringify(attributes, null, 2)}</pre>
      {children}
    </div>
  );
}
`;
}

function componentScss(def) {
  return `@use "../../../styles/base/mixins" as *;

.root {
  // ${def.component} styles
}
`;
}

function renderDrupalConfig(def, sharedFields) {
  const files = [];
  const typeUuid = uuidv5(`paragraphs.paragraphs_type.${def.id}`);

  files.push({
    name: `paragraphs.paragraphs_type.${def.id}.yml`,
    contents: `uuid: ${typeUuid}
langcode: en
status: true
dependencies: {  }
id: ${def.id}
label: ${JSON.stringify(def.label)}
icon_uuid: null
icon_default: null
description: ''
behavior_plugins: {  }
`,
  });

  files.push({
    name: `README-${def.id}.md`,
    contents: `# Drupal import notes: ${def.label}

This file is an artifact for the Drupal project. Do not import it from Next.js.

1. Copy YAML in this folder into the Drupal repo \`config/sync\` (or equivalent).
2. If a field name already exists on another paragraph, reuse its **field storage** — do not import a second \`field.storage.paragraph.*\` with the same name.
3. Add \`${def.id}\` to the allowed bundles on parent fields (${def.parents.map((parent) => parent.field).join(", ") || "none declared"}). Merge that change; do not replace the whole parent field config.
4. Run \`drush cim\` on the Drupal environment.

Shared fields (storage already exists, instance YAML only): ${[...sharedFields].join(", ") || "(none)"}
`,
  });

  for (const [fieldName, field] of Object.entries(def.fields)) {
    const spec = SUPPORTED_FIELD_TYPES[field.type];
    const instanceUuid = uuidv5(`field.field.paragraph.${def.id}.${fieldName}`);
    const shared = sharedFields.has(fieldName);
    const cardinality = isUnlimited(field) ? -1 : 1;

    if (!shared) {
      const storageUuid = uuidv5(`field.storage.paragraph.${fieldName}`);
      files.push({
        name: `field.storage.paragraph.${fieldName}.yml`,
        contents: `uuid: ${storageUuid}
langcode: en
status: true
dependencies:
  module:
    - paragraphs
    - ${field.type === "paragraph" ? "entity_reference_revisions" : field.type === "media" ? "media" : "paragraphs"}
id: paragraph.${fieldName}
field_name: ${fieldName}
entity_type: paragraph
type: ${spec.drupal}
settings: {  }
module: ${field.type === "paragraph" ? "entity_reference_revisions" : field.type === "media" ? "core" : "core"}
locked: false
cardinality: ${cardinality}
translatable: true
indexes: {  }
persist_with_no_fields: false
custom_storage: false
`,
      });
    }

    files.push({
      name: `field.field.paragraph.${def.id}.${fieldName}.yml`,
      contents: `uuid: ${instanceUuid}
langcode: en
status: true
dependencies:
  config:
    - paragraphs.paragraphs_type.${def.id}
    - field.storage.paragraph.${fieldName}
id: paragraph.${def.id}.${fieldName}
field_name: ${fieldName}
entity_type: paragraph
bundle: ${def.id}
label: ${JSON.stringify(fieldName.replace(/^field_/, "").replace(/_/g, " "))}
description: ''
required: false
translatable: true
default_value: {  }
default_value_callback: ''
settings: {  }
field_type: ${spec.drupal}
`,
    });
  }

  return files;
}

function writeIfChanged(filePath, contents, dryRun, created, updated) {
  const next = contents.endsWith("\n") ? contents : `${contents}\n`;
  const exists = fs.existsSync(filePath);
  const previous = exists ? fs.readFileSync(filePath, "utf8") : null;
  if (previous === next) return "unchanged";
  if (dryRun) {
    console.log(`[dry-run] ${exists ? "update" : "write"} ${path.relative(rootDir(), filePath)}`);
    return exists ? "update" : "create";
  }
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, next, "utf8");
  (exists ? updated : created).push(path.relative(rootDir(), filePath));
  return exists ? "update" : "create";
}

function parseArgs(argv) {
  return {
    check: argv.includes("--check"),
    dryRun: argv.includes("--dry-run"),
  };
}

function runGenerate(options = {}) {
  const root = rootDir();
  const { check, dryRun } = options;
  const { project, projectFile, paragraphs } = loadDefinitions(root);
  const errors = validateAll(project, projectFile, paragraphs);

  if (errors.length) {
    console.error("[Paragraphs] Invalid definitions:\n");
    for (const error of errors) {
      console.error(`  - ${error}`);
    }
    process.exitCode = 1;
    return false;
  }

  const sharedFields = new Set(extraList(project, "sharedFields"));
  const model = buildRegistryModel(project, paragraphs);
  const created = [];
  const updated = [];
  const planned = [];

  const files = [
    { path: path.join(root, "src/lib/drupal/generated/paragraph-types.generated.ts"), contents: renderTypes(paragraphs) },
    { path: path.join(root, "src/lib/drupal/generated/paragraph-registry.generated.ts"), contents: renderRegistry(model) },
    { path: path.join(root, "src/components/paragraphs/paragraph-components.generated.tsx"), contents: renderComponentMapping(paragraphs) },
  ];

  for (const file of files) {
    const status = writeIfChanged(file.path, file.contents, dryRun || check, created, updated);
    if (status !== "unchanged") planned.push(path.relative(root, file.path));
  }

  for (const def of paragraphs) {
    if (!def.component) continue;
    const dir = path.join(root, "src/components/paragraphs", def.component);
    const tsx = path.join(dir, `${def.component}.tsx`);
    const scss = path.join(dir, `${def.component}.module.scss`);
    if (!fs.existsSync(tsx)) {
      writeIfChanged(tsx, componentStub(def), dryRun || check, created, updated);
      planned.push(path.relative(root, tsx));
      if (!fs.existsSync(scss)) {
        writeIfChanged(scss, componentScss(def), dryRun || check, created, updated);
        planned.push(path.relative(root, scss));
      }
    }

    if (def.drupalConfig) {
      for (const artifact of renderDrupalConfig(def, sharedFields)) {
        const artifactPath = path.join(root, "generated/drupal-config", def.id, artifact.name);
        const status = writeIfChanged(artifactPath, artifact.contents, dryRun || check, created, updated);
        if (status !== "unchanged") planned.push(path.relative(root, artifactPath));
      }
    }
  }

  if (check) {
    if (planned.length) {
      console.error("[Paragraphs] Generated files are stale:");
      for (const file of planned) console.error(`  - ${file}`);
      console.error("\nRun: npm run paragraphs:generate");
      process.exitCode = 1;
      return false;
    }
    console.log("[Paragraphs] Generated files are up to date.");
    return true;
  }

  console.log("[Paragraphs]");
  console.log("Validated paragraph definitions.");
  if (created.length) {
    console.log("Created:");
    for (const file of created) console.log(`  ✓ ${file}`);
  }
  if (updated.length) {
    console.log("Updated:");
    for (const file of updated) console.log(`  ✓ ${file}`);
  }
  if (!created.length && !updated.length) {
    console.log("No file changes.");
  }
  console.log("Done.");
  return true;
}

if (require.main === module) {
  runGenerate(parseArgs(process.argv.slice(2)));
}

module.exports = { runGenerate };
